(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["microbiology-exam-1"]={"title":"Microbiology Exam 1","sections":[{"id":"pathogens","title":"L1 · Types of Pathogens","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"structures","title":"L1 · Bacterial Structures","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"gram","title":"L1 · Gram Stain","style":"--acc:#2f6f8a;--acc-bg:#e2ebef;--acc-zebra:#f0f5f7;--acc-ink:#25576c"},{"id":"curves","title":"L1 · Growth & Death Curves","style":"--acc:#a4502a;--acc-bg:#f2e6e1;--acc-zebra:#f9f3f0;--acc-ink:#803e21"},{"id":"viruses","title":"L1 · Viruses & Phages","style":"--acc:#6a4fa3;--acc-bg:#eae6f2;--acc-zebra:#f5f3f9;--acc-ink:#533e7f"},{"id":"l2-selection","title":"L2 · Terms & Drug Selection","style":"--acc:#7a3f8a;--acc-bg:#ece4ef;--acc-zebra:#f6f2f7;--acc-ink:#5f316c"},{"id":"l2-index","title":"L2 · Therapeutic Index & Clearance","style":"--acc:#b03a4a;--acc-bg:#f4e3e6;--acc-zebra:#f9f1f2;--acc-ink:#892d3a"},{"id":"l2-lines","title":"L2 · Drug Lines & Their Organisms","style":"--acc:#8a6a2f;--acc-bg:#efeae2;--acc-zebra:#f7f5f0;--acc-ink:#6c5325"},{"id":"l2-moa","title":"L2 · Mechanisms of Action","style":"--acc:#2f7d76;--acc-bg:#e2edec;--acc-zebra:#f0f6f5;--acc-ink:#25625c"},{"id":"l2-resistance","title":"L2 · Resistance & Problems","style":"--acc:#c1873a;--acc-bg:#f6eee3;--acc-zebra:#fbf7f1;--acc-ink:#97692d"},{"id":"micro-l3-1","title":"L3 · Flora & the Two Definitions","style":"--acc:#3f8a55;--acc-bg:#e8f4ea;--acc-zebra:#f2f9f4;--acc-ink:#1f4d2b"},{"id":"micro-l3-2","title":"L3 · Pathogens, Dose & Adhesion","style":"--acc:#1f4d2b;--acc-bg:#e8f4ea;--acc-zebra:#f2f9f4;--acc-ink:#1f4d2b"},{"id":"micro-l3-3","title":"L3 · ★ ENDOTOXIN vs EXOTOXIN","style":"--acc:#c2903a;--acc-bg:#e8f4ea;--acc-zebra:#f2f9f4;--acc-ink:#1f4d2b"},{"id":"micro-l3-4","title":"L3 · Patterns & Manifestations","style":"--acc:#3f8a55;--acc-bg:#e8f4ea;--acc-zebra:#f2f9f4;--acc-ink:#1f4d2b"},{"id":"micro-l3-5","title":"L3 · Reservoirs & Transmission","style":"--acc:#1f4d2b;--acc-bg:#e8f4ea;--acc-zebra:#f2f9f4;--acc-ink:#1f4d2b"},{"id":"micro-l3-6","title":"L3 · ★ NOSOCOMIAL INFECTIONS","style":"--acc:#c2903a;--acc-bg:#e8f4ea;--acc-zebra:#f2f9f4;--acc-ink:#1f4d2b"},{"id":"micro-l3-7","title":"L3 · Epidemiology & Koch","style":"--acc:#3f8a55;--acc-bg:#e8f4ea;--acc-zebra:#f2f9f4;--acc-ink:#1f4d2b"}],"rows":[{"t":"Prokaryotic vs eukaryotic","d":"PRO: no nuclear membrane, few organelles, circular naked DNA, peptidoglycan wall, 70S ribosomes. EU: nuclear membrane, many organelles, linear DNA + histones, carbohydrate wall, 80S ribosomes.","s":0},{"t":"The five types","d":"Bacteria (prokaryotic) · fungi, protozoa, helminths (eukaryotic) · viruses (noncellular infectious agents).","s":0},{"t":"Chlamydias vs Rickettsias","d":"Both tiny obligate intracellular. Rickettsias ARE arthropod-transmitted (fleas, ticks, lice); Chlamydias are NOT.","s":0},{"t":"Mycoplasmas","d":"Tiny, pleomorphic, LACK A CELL WALL. M. pneumoniae.","s":0},{"t":"Fungi","d":"Yeasts unicellular (Candida albicans) · molds multicellular and filamentous (Penicillium notatum).","s":0},{"t":"Protozoa","d":"Trophozoite = motile feeding; cyst = dormant resistant. Apicomplexa essentially nonmotile — Plasmodium.","s":0},{"t":"Helminths","d":"Flatworms: no body cavity, blind-pouch gut. Roundworms: complete gut, cuticle, spines and hooks.","s":0},{"t":"Prion vs viroid","d":"PRION = misfolded protein, NO nucleic acid. VIROID = short RNA, NO protein coat, plants only.","s":0},{"t":"Flagellum / pilus / fimbriae","d":"Motility · plasmid-coded, CONJUGATION · adhesion to membranes.","s":1},{"t":"Glycocalyx","d":"Biofilms · prevents desiccation · prevents phagocytosis (pathogenicity factor).","s":1},{"t":"Plasmids","d":"Small circular dsDNA, NOT essential. May encode antibiotic resistance, metal tolerance, enzymes, toxins.","s":1},{"t":"Endospores","d":"Survival mechanism. BACILLUS and CLOSTRIDIUM.","s":1},{"t":"Peptidoglycan","d":"NAG + NAM alternating, crosslinked by a short peptide bridge. TRANSPEPTIDASES = target of beta lactams.","s":2},{"t":"Steps","d":"Crystal violet → iodine → DECOLORIZE acetone alcohol ~10s (MOST CRITICAL) → safranin.","s":2},{"t":"Gram positive","d":"Thick peptidoglycan + teichoic acids. RETAINS crystal violet → purple. PHYSICALLY strong.","s":2},{"t":"Gram negative","d":"Outer membrane (LPS) + periplasm + thin peptidoglycan. LOSES it → red. CHEMICALLY strong.","s":2},{"t":"Lipopolysaccharide","d":"LIPID A (endotoxin) · core polysaccharide · O-POLYSACCHARIDE (classification).","s":2},{"t":"Growth","d":"Increase in NUMBER, not size, by binary fission → exponential.","s":3},{"t":"Four phases","d":"Lag (adjustment) → exponential (MOST VULNERABLE, e.g. penicillin) → stationary (growth = death) → death (exponential, in own wastes).","s":3},{"t":"Death curve","d":"Rate of death under a control method is CONSTANT. Decimal reduction time = time to kill 90%.","s":3},{"t":"6 phage steps","d":"Adsorption → penetration → replication → assembly → maturation → release.","s":4},{"t":"Lytic vs lysogenic","d":"LYTIC: host destroyed, generalized transduction. LYSOGENIC: prophage, may gain a toxin gene, immune to reinfection, specialized transduction.","s":4},{"t":"Animal vs phage","d":"Entire virion ENGULFED · UNCOATING required · release by BUDDING.","s":4},{"t":"Antibiotic (precisely)","d":"A substance PRODUCED BY A MICROBE that in small amounts inhibits another microbe. Antimicrobial drug = interferes with microbial growth in a host. Chemotherapy = use of drugs to treat disease.","s":5},{"t":"MBC vs MIC","d":"MBC = minimum level killing 99.9% of test organisms (bactericidal). MIC = minimum level inhibiting growth (bacteriostatic).","s":5},{"t":"What makes a good agent","d":"Selective toxicity · favourable pharmacokinetics · appropriate spectrum · few side effects · low toxicity · low hypersensitivity · good therapeutic index · LITTLE resistance development.","s":5},{"t":"Eukaryotic pathogens","d":"Harder — cell structure and physiology resemble the host, so great possibility of toxic side effects. Fewer drugs available.","s":5},{"t":"Choosing the agent","d":"Kirby Bauer disk diffusion (zone corrected for concentration, molecular weight, diffusion). E test = MIC read directly in µg/ml where the zone meets the strip.","s":5},{"t":"Therapeutic window","d":"Range of plasma concentrations spanning minimum concentration for efficacy and for toxicity.","s":6},{"t":"Therapeutic index","d":"TI = max tolerated dose ÷ MIC = TD50 ÷ ED50. HIGHER = wider safety margin = safer drug.","s":6},{"t":"Drug clearance","d":"Renal + hepatic + all other tissues. Drives dosing: do NOT let concentration fall below MIC, and remember onset is not instant.","s":6},{"t":"Fungi produce","d":"Penicillin ← Penicillium chrysogenum · cephalosporins ← Cephalosporium acremonium · griseofulvin ← Penicillium griseofulvum.","s":7},{"t":"Gram-positive rods produce","d":"Bacitracin ← Bacillus subtilis · polymyxin ← Paenibacillus polymyxa.","s":7},{"t":"Actinomycetes produce (most)","d":"Chloramphenicol ← S. venezuelae · streptomycin ← S. griseus · neomycin ← S. fradiae · tetracycline ← S. aurofaciens · amphotericin B ← S. nodosus · nystatin ← S. noursei.","s":7},{"t":"THE TWO EXCEPTIONS","d":"Gentamycin ← MICROMONOSPORA purpurea. Erythromycin ← SACCHAROPOLYSPORA erythraea. Both non-Streptomyces — high yield.","s":7},{"t":"Other","d":"Vancomycin ← Amycolatopsis orientalis · rifamycin ← Amycolatopsis rifamycinica. Quinolones and sulfonamides are ARTIFICIAL (sulfa from coal tar dyes, Domagk 1935).","s":7},{"t":"5 targets","d":"Cell wall · protein synthesis · nucleic acid · plasma membrane · essential metabolites.","s":8},{"t":"Cell wall","d":"Penicillins (PBPs, transpeptidase, autolysins) · cephalosporins (1st Gram+ → 4th oral) · bacitracin (bactoprenol; TOPICAL only) · vancomycin (binds NAG/NAM; last line vs resistant S. aureus) · isoniazid (mycolic synthesis) vs ethambutol (its incorporation).","s":8},{"t":"Protein synthesis","d":"Chloramphenicol 50S peptide bond · aminoglycosides 30S codon misreading · tetracyclines tRNA attachment · streptogramins TWO components on 50S · erythromycin 50S translocation.","s":8},{"t":"Nucleic acid","d":"Rifamycin — RNA polymerase (TB). Quinolones — DNA GYRASE (UTI, hospital-acquired).","s":8},{"t":"Membrane / metabolites","d":"Polymyxin B — attaches lipid components of outer + inner membrane (topical). Sulfonamides — mimic PABA, block folate.","s":8},{"t":"Antifungals","d":"POLYENES bind ergosterol → pores. AZOLES block ergosterol SYNTHESIS. ECHINOCANDINS block beta-glucan (CELL WALL, not membrane). Griseofulvin — microtubules. Tolnaftate — squalene epoxidase.","s":8},{"t":"Antivirals","d":"Remdesivir — nucleotide analog, terminates RNA transcription · protease inhibitors · integrase inhibitors · CCR5 block (attachment) · neuraminidase (escape) · amantadine (uncoating) · interferon (alpha in hepatitis; PEG = finite duration BUT greater adverse effects).","s":8},{"t":"Resistance defined","d":"Avoiding an antibiotic's effects by DESTROYING it, TRANSPORTING it out, or CHANGING to block it.","s":9},{"t":"Why it occurs","d":"Genetic variation means some are already less susceptible; the antibiotic SELECTS them. The drug does not create resistance.","s":9},{"t":"Genetic mechanisms","d":"Random mutation · plasmid swapping (conjugation) · transposons · transduction · transformation · binary fission shares all.","s":9},{"t":"Biochemical mechanisms","d":"No access: decreased permeability (beta-lactams, quinolones), decreased transport (aminoglycosides), increased efflux (tetracyclines, quinolones). Inactivation: beta-lactamases. Target modification: gyrase. Bypass: vanA, vanB, TMP.","s":9},{"t":"Biofilms + ESKAPE","d":"Barrier sequesters drug · organisms metabolically LESS active · proximity ENHANCES gene transfer. ESKAPE = E. faecium, S. aureus, K. pneumoniae, A. baumannii, P. aeruginosa, Enterobacter.","s":9},{"t":"4 problems with therapy","d":"SUPERINFECTION · DIRECT TOXICITY · HYPERSENSITIVITY · RESISTANCE.","s":9},{"t":"Direct toxicity (high yield)","d":"Aminoglycosides = renal + AUDITORY · chloramphenicol = aplastic anaemia · ciprofloxacin = seizures · doxycycline = oesophageal ulcers · tetracycline = tooth discoloration (binds calcium during development) · amphotericin B = renal + hepatic · sulfamethoxazole = hyperkalaemia · chloroquine = dysrhythmias.","s":9},{"t":"Hypersensitivity","d":"Mostly BETA LACTAMS (penicillin, cephalosporins) and quinolones. Immediate or delayed; hives → anaphylaxis.","s":9},{"t":"Drug combinations","d":"Indifference (no interaction) · SYNERGISM (greater than either) · ANTAGONISM (less than either).","s":9},{"t":"INFECTION vs DISEASE","d":"INFECTION = microbes PENETRATE HOST DEFENCES, ENTER TISSUES AND MULTIPLY. DISEASE = ANY DEVIATION FROM HEALTH, microbial or not. Disease is the BROADER term.","s":10},{"t":"RESIDENT FLORA","d":"Bacteria, fungi, protozoa, viruses AND ARTHROPODS. Most areas in contact with the outside environment carry them.","s":10},{"t":"HIGHEST NUMBERS","d":"LARGE INTESTINE — mainly STRICT or FACULTATIVE ANAEROBES. Bacteria are 10–30% OF FAECAL VOLUME.","s":10},{"t":"Skin flora","d":"STAPHYLOCOCCI, CORYNEBACTERIUM, PROPIONIBACTERIUM, YEASTS, MYCOBACTERIUM SMEGMATIS.","s":10},{"t":"Oral flora","d":"AEROBIC STREPTOCOCCI are the most common oral residents.","s":10},{"t":"Respiratory flora","d":"STAPH. AUREUS, NEISSERIA MENINGITIDIS. The LOWER RESPIRATORY TRACT IS ESSENTIALLY STERILE.","s":10},{"t":"STERILE SITES","d":"Heart and blood vessels · kidneys and bladder · brain and spinal column · middle and inner ear · interior of the eyes · BLOOD AND CSF (cerebrospinal fluid) · urine in the kidneys and bladder · AMNIOTIC FLUID.","s":10},{"t":"The numbers","d":"~30 TRILLION human cells vs ~38 TRILLION non-human. ~50% of the human genome is NON-HUMAN genetic material.","s":10},{"t":"TRUE (FRANK) PATHOGEN","d":"Causes disease in HEALTHY people with NORMAL defences. INFLUENZA, RABIES, PLAGUE BACTERIUM, MALARIAL PROTOZOAN.","s":11},{"t":"OPPORTUNISTIC PATHOGEN","d":"Causes disease when defences are COMPROMISED, or when it grows somewhere UNNATURAL to it. SOMETIMES IT IS THE PATIENT'S OWN FLORA.","s":11},{"t":"WEAKENS HOST DEFENCES","d":"AGE (elderly, young children, premature infants) · genetic/acquired immunological defects · IMMUNOSUPPRESSING DRUGS AND ORGAN TRANSPLANTS · STRESS · chronic conditions (liver disease, diabetes) · INFLAMMATION · primary infections. Write them as COMORBIDITIES.","s":11},{"t":"PORTALS OF ENTRY","d":"SKIN · GASTROINTESTINAL · RESPIRATORY · UROGENITAL · CONJUNCTIVA · PREGNANCY AND BIRTH. EXOGENOUS (outside) or ENDOGENOUS (within).","s":11},{"t":"INFECTIOUS DOSE (ID50)","d":"MINIMUM microbes needed to infect 50% of a population. SMALL ID50 = GREATER VIRULENCE.","s":11},{"t":"The ID50 range","d":"MEASLES 1 PARTICLE · TB 10 bacteria · smallpox 10–100 · plague 100–500 · SARS-CoV-1 ~280 · influenza A ~790 · gonorrhoea 1,000 · CHOLERA 100,000,000.","s":11},{"t":"ADHESION MECHANISMS","d":"FIMBRIAE (attachment pili) · FLAGELLA · ADHESIVE SLIMES/CAPSULES (dextran slime, glycocalyx) · SUCTION DISKS of protozoans · VIRAL SPIKE or CAPSID PROTEINS · HOOKS AND BARBS of helminths and insect larvae.","s":11},{"t":"ENDOTOXIN — what","d":"LIPID A OF THE LIPOPOLYSACCHARIDE.","s":12},{"t":"ENDOTOXIN — who","d":"GRAM-NEGATIVE ONLY. It is part of their outer membrane.","s":12},{"t":"ENDOTOXIN — released how","d":"FROM LYSED OR DAMAGED bacteria — i.e. when the organism DIES.","s":12},{"t":"EXOTOXIN — what","d":"PROTEINS.","s":12},{"t":"EXOTOXIN — who","d":"Certain GRAM-POSITIVE AND GRAM-NEGATIVE bacteria.","s":12},{"t":"EXOTOXIN — released how","d":"SECRETED BY LIVING bacteria.","s":12},{"t":"The one-liner","d":"ENDO = STRUCTURAL LIPID FROM A DEAD GRAM-NEGATIVE. EXO = PROTEIN SECRETED BY A LIVING ORGANISM, EITHER GRAM.","s":12},{"t":"EXOENZYMES","d":"Attack host defences to allow DEEPER INVASION: MUCINASE, HYALURONIDASE, COAGULASE, BACTERIAL KINASES.","s":12},{"t":"TOXIGENICITY","d":"Capacity to produce toxins, grouped by TISSUE TARGETED: NEUROTOXINS, ENTEROTOXINS, HEMOTOXINS, NEPHROTOXINS.","s":12},{"t":"ANTIPHAGOCYTIC FACTORS","d":"LEUKOCIDINS destroy leukocytes (-cidin = to kill). CAPSULES avoid phagocytosis or resist digestion inside the phagocyte.","s":12},{"t":"LOCALIZED","d":"Confined to a specific tissue. BOILS, WARTS.","s":13},{"t":"SYSTEMIC","d":"Spreads to SEVERAL SITES via the bloodstream. MEASLES, CHICKEN POX, ANTHRAX, RABIES.","s":13},{"t":"FOCAL","d":"An agent BREAKS LOOSE from a local site and spreads.","s":13},{"t":"MIXED","d":"SEVERAL MICROBES growing SIMULTANEOUSLY at one site.","s":13},{"t":"PRIMARY / SECONDARY","d":"PRIMARY = the initial infection. SECONDARY = a DIFFERENT microbe complicating it, e.g. bacterial lung infection on top of a viral URI.","s":13},{"t":"SUPERINFECTION","d":"A secondary infection from DISRUPTION OF THE NATURAL MICROFLORA. Classic: ANTIBIOTICS FOR STREP THROAT → VAGINAL YEAST INFECTION. IF THE STEM MENTIONS ANTIBIOTICS, IT IS A SUPERINFECTION.","s":13},{"t":"SIGN","d":"OBJECTIVE evidence noted by an OBSERVER; often more precise and MAY BE MEASURED. Example: INFLAMED PHARYNX.","s":13},{"t":"SYMPTOM","d":"SUBJECTIVE evidence SENSED AND DESCRIBED BY THE PATIENT. Example: SORE THROAT.","s":13},{"t":"SEQUELAE","d":"LONG-TERM OR PERMANENT damage: PARALYSIS from polio · BLINDNESS from gonococcal conjunctivitis · STERILITY from syphilis · DEAFNESS from meningitis · ARTHRITIS from Lyme disease.","s":13},{"t":"PORTAL OF EXIT","d":"How pathogens DEPART the host — and therefore how they reach the next one.","s":13},{"t":"RESERVOIR","d":"The PRIMARY HABITAT from which a pathogen ORIGINATES. Living or nonliving.","s":14},{"t":"Living reservoirs","d":"Someone with an OBVIOUS ACTIVE INFECTION is likely contagious. ASYMPTOMATIC CARRIERS may be HUMANS OR ANIMALS.","s":14},{"t":"PASSIVE CARRIERS","d":"MEDICAL OR DENTAL PERSONNEL — carrying it without being infected.","s":14},{"t":"VECTORS","d":"A LIVE ANIMAL that transmits disease: MOSQUITOES, FLEAS, TICKS; also FLIES, FRUIT FLIES, COCKROACHES.","s":14},{"t":"NONLIVING RESERVOIRS","d":"SOIL AND WATER.","s":14},{"t":"ZOONOSIS","d":"Animal infections spread to humans and vice versa. Can be BACTERIAL, VIRAL, FUNGAL OR PROTOZOAN. CANNOT BE ELIMINATED WITHOUT ERADICATING THE ANIMAL RESERVOIR.","s":14},{"t":"DIRECT transmission","d":"HORIZONTAL (kissing, sexual) · VERTICAL (MOTHER TO CHILD, transplacental or vaginal birth) · DROPLET (saliva, vomit, faeces, blood) · BIOLOGICAL VECTORS.","s":14},{"t":"INDIRECT transmission","d":"VEHICLES and FOMITES (inanimate objects), and AIRBORNE DROPLET NUCLEI.","s":14},{"t":"DEFINITION","d":"HAI = HOSPITAL-ACQUIRED INFECTION. ACQUIRED OR DEVELOPING DURING A HOSPITAL STAY. May PROLONG THE STAY OR END IN DEATH.","s":15},{"t":"MOST COMMON SITES","d":"URINARY TRACT · RESPIRATORY TRACT · SURGICAL INCISIONS.","s":15},{"t":"MOST COMMON ORGANISMS","d":"Gram-negative: E. COLI, PSEUDOMONAS, KLEBSIELLA. Gram-positive: STAPHYLOCOCCI, STREPTOCOCCI. Fungi: YEASTS. The wider list goes by ESKAPE.","s":15},{"t":"MITIGATION — the answer","d":"UNIVERSAL PRECAUTIONS for sample collection and patient care, based on the assumption that ALL PATIENT SPECIMENS ARE POSSIBLY INFECTIOUS. You do not decide which to be careful with.","s":15},{"t":"The fomite link","d":"An INANIMATE OBJECT carries the organism between patients — which is why the same few organisms keep reappearing.","s":15},{"t":"EPIDEMIOLOGY","d":"Study of the FREQUENCY AND DISTRIBUTION of disease in human populations.","s":16},{"t":"REPORTABLE / NOTIFIABLE","d":"Must be reported to PUBLIC HEALTH AUTHORITIES. In the US the CDC publishes the MORBIDITY AND MORTALITY WEEKLY REPORT.","s":16},{"t":"PREVALENCE","d":"TOTAL EXISTING cases against the entire population, usually A PERCENTAGE.","s":16},{"t":"INCIDENCE","d":"NEW cases OVER A TIME PERIOD, against the general healthy population.","s":16},{"t":"MORTALITY RATE","d":"DEATHS due to a disease, PER 100,000.","s":16},{"t":"MORBIDITY RATE","d":"CASES — people afflicted — PER 100,000.","s":16},{"t":"THE 100-YEAR TREND","d":"DEATH RATE DROPPED while MORBIDITY REMAINED RELATIVELY HIGH. People stopped DYING of these; they did not stop GETTING them.","s":16},{"t":"ENDEMIC","d":"STEADY frequency over a long period in a particular LOCATION, often because the RESERVOIR IS PRESENT.","s":16},{"t":"SPORADIC","d":"OCCASIONAL cases at IRREGULAR intervals.","s":16},{"t":"EPIDEMIC","d":"Prevalence INCREASING BEYOND WHAT IS EXPECTED for that population.","s":16},{"t":"PANDEMIC","d":"A GLOBAL epidemic.","s":16},{"t":"KOCH'S POSTULATES (1880s)","d":"1. FIND the microbe in EVERY CASE. 2. ISOLATE and CULTIVATE IT ARTIFICIALLY. 3. INOCULATE a susceptible healthy subject. 4. RE-ISOLATE from the new subject.","s":16},{"t":"WHERE KOCH FAILS","d":"Organisms that CANNOT BE CULTIVATED ARTIFICIALLY — M. LEPRAE and LEGIONELLA PNEUMOPHILA. VIRUSES AND PRIONS break all the old rules.","s":16},{"t":"MOLECULAR KOCH (Falkow, 1988)","d":"1. The PROPERTY should ASSOCIATE WITH PATHOGENIC STRAINS. 2. INACTIVATING the gene should cause MEASURABLE LOSS OF VIRULENCE. 3. REVERTING it should RESTORE pathogenicity. The shift is FROM THE ORGANISM TO THE GENE.","s":16}],"map":{"microbiology-exam-1-antibiotics-resistance-quiz-version-2":[38,-1,44,51,43,-1,48,23,37,-1,-1,47,30,49,28,48,34,24,48,37,-1,40,-1,46,26,-1,29,27,48,-1],"microbiology-exam-1-antibiotics-resistance-quiz":[-1,48,26,43,37,-1,-1,47,42,48,39,45,29,-1,-1,41,42,30,27,45,38,43,48,24,-1,37,46,41,48,50],"microbiology-exam-1-general-microbiology-quiz-version-2":[1,21,-1,-1,22,0,19,17,19,17,21,12,1,14,21,12,45,-1,15,8,19,16,-1,5,-1,-1,-1,59,4,16],"microbiology-exam-1-general-microbiology-quiz":[-1,-1,39,-1,22,1,10,15,-1,39,-1,1,13,39,19,-1,-1,20,20,17,-1,11,9,3,-1,8,66,17,-1,2],"microbiology-exam-1-microbe-human-interactions-quiz-version-2":[111,110,62,90,89,63,92,68,64,94,64,86,91,62,85,104,63,106,94,97,53,59,57,87,95,108,107,82,54,74],"microbiology-exam-1-microbe-human-interactions-quiz":[66,85,59,79,81,78,56,75,72,83,-1,61,95,80,77,96,59,66,58,69,76,93,53,101,101,53,96,-1,102,103]}};
